<?php require __DIR__.'/../includes/functions.php'; require_login('admin'); $id=(int)($_GET['id']??0);$q=db()->prepare("SELECT u.*,p.* FROM users u LEFT JOIN student_profiles p ON p.user_id=u.id WHERE u.id=? AND u.role='student'");$q->execute([$id]);$s=$q->fetch();if(!$s)redirect('/admin/index.php');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$b=trim($_POST['body']??'');if($b)db()->prepare("INSERT INTO messages(student_id,sender_role,body) VALUES(?, 'admin', ?)")->execute([$id,$b]);flash('پیام ارسال شد.');redirect('/admin/student.php?id='.$id);}db()->prepare("UPDATE messages SET is_read=1 WHERE student_id=? AND sender_role='student'")->execute([$id]);$m=db()->prepare('SELECT * FROM messages WHERE student_id=? ORDER BY created_at DESC');$m->execute([$id]);layout_start('پرونده دانش‌آموز');?><a href="<?=e(url('/admin/index.php'))?>">← بازگشت به فهرست</a><div class="page-head"><div><p class="eyebrow">پرونده محرمانه</p><h1><?=e($s['name'])?></h1></div><?php if($s['emergency_flag']):?><span class="badge danger">نیازمند ارجاع/پیگیری</span><?php endif;?></div><div class="details card"><div><b>موبایل:</b> <?=e($s['mobile'])?></div><div><b>کد ملی:</b> <?=e($s['national_id']??'—')?></div><div><b>تولد:</b> <?=e($s['birth_date']??'—')?></div><div><b>والد:</b> <?=e($s['parent_name']??'—')?> / <?=e($s['parent_phone']??'—')?></div><div><b>تماس اضطراری:</b> <?=e($s['emergency_contact']??'—')?> / <?=e($s['emergency_phone']??'—')?></div><div><b>حساسیت‌ها:</b> <?=nl2br(e($s['allergies']??'—'))?></div><div><b>نکات سلامت:</b> <?=nl2br(e($s['health_notes']??'—'))?></div><div><b>پایه / رشته:</b> <?=e($s['grade']??'—')?> / <?=e($s['study_field']??'—')?></div><div><b>نقاط قوت:</b> <?=nl2br(e($s['strengths']??'—'))?></div><div><b>درس‌های نیازمند کمک:</b> <?=nl2br(e($s['difficult_subjects']??'—'))?></div><div><b>هدف تحصیلی:</b> <?=nl2br(e($s['academic_goal']??'—'))?></div><div><b>روش یادگیری:</b> <?=e($s['learning_style']??'—')?></div><div><b>علایق:</b> <?=nl2br(e($s['interests']??'—'))?></div><div><b>حال عمومی:</b> <?=e($s['current_mood']??'—')?></div><div><b>ارتباط ترجیحی:</b> <?=e($s['communication_preference']??'—')?></div><div><b>امکانات مطالعه:</b> <?=e($s['study_resources']??'—')?></div><div><b>درخواست حمایت:</b> <?=e($s['support_request']??'—')?></div><div class="full"><b>یادداشت دانش‌آموز:</b> <?=nl2br(e($s['student_note']??'—'))?></div><div><b>وضعیت حمایتی:</b> <?=e($s['household_status']??'—')?></div><div><b>سرپرست اصلی:</b> <?=e($s['primary_caregiver']??'—')?> / <?=e($s['caregiver_phone']??'—')?></div><div class="full"><b>نشانی:</b> <?=nl2br(e($s['address']??'—'))?></div></div><div class="card"><h2>پیام‌ها</h2><?php while($x=$m->fetch()):?><article class="message <?=e($x['sender_role'])?>"><small><?=e($x['sender_role']==='admin'?'مدیر':'دانش‌آموز')?> · <?=e($x['created_at'])?></small><p><?=nl2br(e($x['body']))?></p></article><?php endwhile;?><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>پیام جدید<textarea name="body" required></textarea></label><button class="button">ارسال پیام</button></form></div><?php layout_end(); ?>
